import{_ as i,o as a,c as l,ah as s}from"./chunks/framework.CPHJ30oF.js";const p=JSON.parse('{"title":"12-Docker依赖控制与Healthcheck最佳实践","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"为什么需要健康检查","slug":"为什么需要健康检查","link":"#为什么需要健康检查","children":[]},{"level":2,"title":"Docker HEALTHCHECK 语法","slug":"docker-healthcheck-语法","link":"#docker-healthcheck-语法","children":[]},{"level":2,"title":"常见健康检查方式","slug":"常见健康检查方式","link":"#常见健康检查方式","children":[{"level":3,"title":"1. HTTP 检查","slug":"_1-http-检查","link":"#_1-http-检查","children":[]},{"level":3,"title":"2. TCP 端口检查","slug":"_2-tcp-端口检查","link":"#_2-tcp-端口检查","children":[]},{"level":3,"title":"3. 脚本检查","slug":"_3-脚本检查","link":"#_3-脚本检查","children":[]}]},{"level":2,"title":"依赖控制与 Docker Compose","slug":"依赖控制与-docker-compose","link":"#依赖控制与-docker-compose","children":[]},{"level":2,"title":"实战建议","slug":"实战建议","link":"#实战建议","children":[]},{"level":2,"title":"依赖控制的典型模式","slug":"依赖控制的典型模式","link":"#依赖控制的典型模式","children":[]},{"level":2,"title":"常见误区","slug":"常见误区","link":"#常见误区","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/12-Docker依赖控制与Healthcheck最佳实践.md","filePath":"docker/12-Docker依赖控制与Healthcheck最佳实践.md"}'),h={name:"docker/12-Docker依赖控制与Healthcheck最佳实践.md"};function t(n,e,c,r,k,d){return a(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="_12-docker依赖控制与healthcheck最佳实践" tabindex="-1">12-Docker依赖控制与Healthcheck最佳实践 <a class="header-anchor" href="#_12-docker依赖控制与healthcheck最佳实践" aria-label="Permalink to “12-Docker依赖控制与Healthcheck最佳实践”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>容器启动成功不等于服务可用，尤其当你的应用依赖数据库、缓存或外部服务时。Docker 的 <code>HEALTHCHECK</code> 机制可以帮助你把“已启动”和“已就绪”区分开，减少启动顺序和依赖问题。</p><p>本篇文章介绍 <code>HEALTHCHECK</code> 的使用方式、依赖控制技巧及和 Compose 的配合实践。</p><h2 id="为什么需要健康检查" tabindex="-1">为什么需要健康检查 <a class="header-anchor" href="#为什么需要健康检查" aria-label="Permalink to “为什么需要健康检查”">​</a></h2><p>很多错误场景来源于服务尚未准备好就开始接受请求：</p><ul><li>数据库还在初始化；</li><li>应用正在加载依赖；</li><li>缓存尚未建立连接。</li></ul><p>这时容器本身可能已经启动，但应用还不能提供正常服务。健康检查能让系统知道：这个实例是否已经达到真正可用状态。</p><h2 id="docker-healthcheck-语法" tabindex="-1">Docker <code>HEALTHCHECK</code> 语法 <a class="header-anchor" href="#docker-healthcheck-语法" aria-label="Permalink to “Docker HEALTHCHECK 语法”">​</a></h2><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HEALTHCHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --interval=30s --timeout=5s --retries=3 CMD curl -f http://localhost:8080/health || exit 1</span></span></code></pre></div><p>参数意义：</p><ul><li><code>--interval</code>：检查间隔；</li><li><code>--timeout</code>：单次检查超时时间；</li><li><code>--retries</code>：连续失败次数；</li><li><code>CMD</code>：执行的检查命令。</li></ul><p>当命令返回非零状态时，容器会被标记为 <code>unhealthy</code>。</p><h2 id="常见健康检查方式" tabindex="-1">常见健康检查方式 <a class="header-anchor" href="#常见健康检查方式" aria-label="Permalink to “常见健康检查方式”">​</a></h2><h3 id="_1-http-检查" tabindex="-1">1. HTTP 检查 <a class="header-anchor" href="#_1-http-检查" aria-label="Permalink to “1. HTTP 检查”">​</a></h3><p>适合 Web 服务：</p><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HEALTHCHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --interval=15s --timeout=3s CMD curl -f http://localhost:3000/health || exit 1</span></span></code></pre></div><h3 id="_2-tcp-端口检查" tabindex="-1">2. TCP 端口检查 <a class="header-anchor" href="#_2-tcp-端口检查" aria-label="Permalink to “2. TCP 端口检查”">​</a></h3><p>适用于数据库或缓存：</p><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HEALTHCHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --interval=15s --timeout=5s CMD nc -z localhost 5432</span></span></code></pre></div><h3 id="_3-脚本检查" tabindex="-1">3. 脚本检查 <a class="header-anchor" href="#_3-脚本检查" aria-label="Permalink to “3. 脚本检查”">​</a></h3><p>当你需要更复杂的就绪判断时，使用自定义脚本：</p><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> healthcheck.sh /usr/local/bin/healthcheck.sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HEALTHCHECK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --interval=30s CMD /usr/local/bin/healthcheck.sh</span></span></code></pre></div><h2 id="依赖控制与-docker-compose" tabindex="-1">依赖控制与 Docker Compose <a class="header-anchor" href="#依赖控制与-docker-compose" aria-label="Permalink to “依赖控制与 Docker Compose”">​</a></h2><p><code>depends_on</code> 只能保证启动顺序，不保证服务已经健康。</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  db</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mysql:8</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">myapp:latest</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    depends_on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">db</span></span></code></pre></div><p>如果你需要真正等待数据库可用，应该结合健康检查或启动等待脚本。</p><h2 id="实战建议" tabindex="-1">实战建议 <a class="header-anchor" href="#实战建议" aria-label="Permalink to “实战建议”">​</a></h2><ol><li>在镜像层定义 <code>HEALTHCHECK</code>；</li><li>对关键依赖使用就绪接口；</li><li>在 Compose 或编排平台中把健康状态作为依赖条件；</li><li>设置合理的重试和超时；</li><li>让健康检查尽量简单且幂等。</li></ol><h2 id="依赖控制的典型模式" tabindex="-1">依赖控制的典型模式 <a class="header-anchor" href="#依赖控制的典型模式" aria-label="Permalink to “依赖控制的典型模式”">​</a></h2><ul><li>数据库服务启动后，等待 <code>mysqld</code> 可连接；</li><li>Web 应用启动后，等待 <code>/health</code> 接口返回正常；</li><li>消息队列启动后，等待连接可用。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to “常见误区”">​</a></h2><ul><li>认为 <code>docker run</code> 成功就说明服务可用；</li><li>误用 <code>depends_on</code> 作为健康检查；</li><li>健康检查太复杂，导致检查本身失败；</li><li>健康检查频率过高，造成额外负载。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>Docker 的健康检查机制是生产稳定性的基础之一。把 <code>HEALTHCHECK</code> 作为镜像构建的一部分，并结合依赖控制策略，你的容器系统会更智能、更可控、更稳健。</p>`,35)])])}const g=i(h,[["render",t]]);export{p as __pageData,g as default};
